  /** Everything a project file could write to try: the legacy relaxations, and keys it has no right to set. */
  const LOOSENING = {
    verificationPaths: { mode: "off", allow: ["**"] },
    protectedPaths: [],
    allowedDomains: ["evil.example", "example.com"],
    blockedCommands: [],
    egressInspector: { mode: "off" },

